CREATE TABLE IF NOT EXISTS shift_cash_sessions(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,employee_email TEXT NOT NULL,shift_entry_id TEXT,expected_cash_cents INTEGER NOT NULL DEFAULT 0,counted_cash_cents INTEGER NOT NULL DEFAULT 0,variance_cents INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'OPEN',submitted_at TEXT,verified_by TEXT,verified_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS shift_cash_denominations(id TEXT PRIMARY KEY,session_id TEXT NOT NULL,denomination_cents INTEGER NOT NULL,quantity INTEGER NOT NULL DEFAULT 0,subtotal_cents INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(session_id) REFERENCES shift_cash_sessions(id));
CREATE TABLE IF NOT EXISTS shift_check_items(id TEXT PRIMARY KEY,session_id TEXT NOT NULL,check_number_masked TEXT,payer_name TEXT,amount_cents INTEGER NOT NULL,document_object_key TEXT,sha256 TEXT,status TEXT NOT NULL DEFAULT 'CAPTURED',posting_status TEXT NOT NULL DEFAULT 'DRAFT',FOREIGN KEY(session_id) REFERENCES shift_cash_sessions(id));
CREATE TABLE IF NOT EXISTS shift_drop_verifications(id TEXT PRIMARY KEY,session_id TEXT NOT NULL,manager_email TEXT NOT NULL,received_cash_cents INTEGER NOT NULL,received_check_cents INTEGER NOT NULL,variance_cents INTEGER NOT NULL,resolution_note TEXT,status TEXT NOT NULL DEFAULT 'VERIFIED',verified_at TEXT NOT NULL,FOREIGN KEY(session_id) REFERENCES shift_cash_sessions(id));
CREATE INDEX IF NOT EXISTS idx_cash_session_scope ON shift_cash_sessions(organization_id,property_id,status,created_at);
